import type {
  ItemsApiGetItemsRequest,
  MediaInfoApiGetPlaybackInfoRequest,
} from "@jellyfin/sdk/lib/generated-client";
import type { SolidQueryOptions } from "@tanstack/solid-query";
import { Effect, pipe } from "effect";
import type { Accessor } from "solid-js";
import {
  createEffectMutation,
  createEffectQuery,
  createQueryDataHelpers,
  createQueryKey,
  type ExtractQueryData,
} from "~/effect/tanstack/query";
import { safeAssign } from "~/lib/utils";
import { JellyfinCatalogueService } from "./service";
import type { Library, MediaItem, PlaybackMetadata } from "./types";

const LIBRARIES_TIMEOUT = "10 seconds";

type ItemQueryOptions = Accessor<
  Omit<
    SolidQueryOptions<
      MediaItem,
      unknown,
      MediaItem,
      ReturnType<typeof JellyfinCatalogueOperations.itemQueryKey>
    >,
    "queryFn" | "queryKey"
  >
>;

type PlaybackMetadataQueryOptions = Accessor<
  Omit<
    SolidQueryOptions<
      PlaybackMetadata,
      unknown,
      PlaybackMetadata,
      ReturnType<typeof JellyfinCatalogueOperations.playbackMetadataQueryKey>
    >,
    "queryFn" | "queryKey"
  >
>;

class JellyfinCatalogue {
  librariesQueryKey = createQueryKey("catalogueLibraries");
  librariesQueryDataHelpers = createQueryDataHelpers<Library[]>(
    this.librariesQueryKey
  );
  getLibraries = () =>
    createEffectQuery(() => ({
      queryKey: this.librariesQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.libraries()),
          Effect.timeout(LIBRARIES_TIMEOUT)
        ),
    }));

  resumeRailQueryKey = createQueryKey("catalogueResumeRail");
  resumeRailQueryDataHelpers = createQueryDataHelpers<MediaItem[]>(
    this.resumeRailQueryKey
  );
  getResumeRail = () =>
    createEffectQuery(() => ({
      queryKey: this.resumeRailQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.resumeRail())
        ),
    }));

  nextUpRailQueryKey = createQueryKey("catalogueNextUpRail");
  nextUpRailQueryDataHelpers = createQueryDataHelpers<MediaItem[]>(
    this.nextUpRailQueryKey
  );
  getNextUpRail = () =>
    createEffectQuery(() => ({
      queryKey: this.nextUpRailQueryKey(),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.nextUpRail({ limit: 4 }))
        ),
    }));

  latestMoviesQueryKey = createQueryKey<
    "catalogueLatestMovies",
    { search: string }
  >("catalogueLatestMovies");
  latestMoviesQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { search: string }
  >(this.latestMoviesQueryKey);
  getLatestMovies = (searchTerm: () => string, libraries?: Library[]) =>
    createEffectQuery(() => {
      const search = searchTerm();
      const movieLibraryId = libraries?.find(
        (library) => library.collectionType === "movies"
      )?.id;

      return {
        queryKey: this.latestMoviesQueryKey({ search }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              search
                ? catalogue.items({
                    parentId: movieLibraryId,
                    enableImages: true,
                    fields: ["ParentId"],
                    includeItemTypes: ["Movie"],
                    limit: 7,
                    recursive: true,
                    searchTerm: search,
                  })
                : catalogue.latestMovieRail({ limit: 7 })
            )
          ),
        enabled: libraries?.some(
          (library) => library.collectionType === "movies"
        ),
      };
    });

  latestTVShowsQueryKey = createQueryKey<
    "catalogueLatestTVShows",
    { search: string }
  >("catalogueLatestTVShows");
  latestTVShowsQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { search: string }
  >(this.latestTVShowsQueryKey);
  getLatestTVShows = (searchTerm: () => string, libraries?: Library[]) =>
    createEffectQuery(() => {
      const search = searchTerm();
      const tvLibraryId = libraries?.find(
        (library) => library.collectionType === "tvshows"
      )?.id;

      return {
        queryKey: this.latestTVShowsQueryKey({ search }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              search
                ? catalogue.items({
                    parentId: tvLibraryId,
                    enableImages: true,
                    fields: ["ParentId"],
                    includeItemTypes: ["Series"],
                    limit: 7,
                    recursive: true,
                    searchTerm: search,
                  })
                : catalogue.latestTvRail({ limit: 7 })
            )
          ),
        enabled: libraries?.some(
          (library) => library.collectionType === "tvshows"
        ),
      };
    });

  itemQueryKey = createQueryKey<"catalogueItem", { id: string }>(
    "catalogueItem"
  );
  itemQueryDataHelpers = createQueryDataHelpers<
    ExtractQueryData<ReturnType<typeof this.getItem>>,
    { id: string }
  >(this.itemQueryKey);
  getItem = (
    id: () => string,
    params?: ItemsApiGetItemsRequest,
    queryOptions?: ItemQueryOptions
  ) =>
    createEffectQuery(() => ({
      queryKey: this.itemQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) =>
            catalogue.itemById(id(), { enableImages: true, ...params })
          )
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  itemsQueryKey = createQueryKey<
    "catalogueItems",
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >("catalogueItems");
  itemsQueryDataHelpers = createQueryDataHelpers<
    MediaItem[],
    { parentId?: string; ids?: string[]; searchTerm?: string }
  >(this.itemsQueryKey);
  getItems = (
    params?:
      | ItemsApiGetItemsRequest
      | Accessor<ItemsApiGetItemsRequest | undefined>
  ) =>
    createEffectQuery(() => {
      const request = typeof params === "function" ? params() : params;

      return {
        queryKey: this.itemsQueryKey({
          parentId: request?.parentId,
          ids: request?.ids,
          searchTerm: request?.searchTerm,
        }),
        queryFn: () =>
          JellyfinCatalogueService.pipe(
            Effect.flatMap((catalogue) =>
              catalogue.items({ enableImages: true, ...request })
            )
          ),
      };
    });

  getNextEpisode = (item: () => MediaItem | undefined) =>
    createEffectQuery(() => ({
      queryKey: ["catalogueNextEpisode", { id: item()?.id }] as const,
      queryFn: () =>
        pipe(
          Effect.fromNullable(item()),
          Effect.flatMap((mediaItem) =>
            JellyfinCatalogueService.pipe(
              Effect.flatMap((catalogue) => catalogue.nextEpisode(mediaItem))
            )
          )
        ),
      enabled: () => Boolean(item()?.id),
    }));

  playbackMetadataQueryKey = createQueryKey<
    "cataloguePlaybackMetadata",
    { id: string }
  >("cataloguePlaybackMetadata");
  playbackMetadataDataHelpers = createQueryDataHelpers<
    PlaybackMetadata,
    { id: string }
  >(this.playbackMetadataQueryKey);
  getPlaybackMetadata = (
    id: () => string,
    params?: MediaInfoApiGetPlaybackInfoRequest,
    queryOptions?: PlaybackMetadataQueryOptions
  ) =>
    createEffectQuery(() => ({
      queryKey: this.playbackMetadataQueryKey({ id: id() }),
      queryFn: () =>
        JellyfinCatalogueService.pipe(
          Effect.flatMap((catalogue) => catalogue.playbackMetadata(id(), params))
        ),
      ...(queryOptions ? queryOptions() : {}),
    }));

  markItemPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { played: true });
            });

            yield* service.markItemPlayed(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemUnPlayed = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemUnPlayed"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", {
                played: false,
                playbackPositionTicks: 0,
              });
            });

            yield* service.markItemUnPlayed(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { favorite: true });
            });

            yield* service.markItemFavorite(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));

  markItemUnFavorite = (id: string, onDone?: () => Promise<void> | void) =>
    createEffectMutation(() => ({
      mutationKey: ["catalogueMarkItemUnFavorite"],
      mutationFn: () =>
        Effect.gen(
          function* (this: JellyfinCatalogue) {
            this.itemQueryDataHelpers.cancelQuery({ id });
            const service = yield* JellyfinCatalogueService;
            const prevData = this.itemQueryDataHelpers.getData({ id });

            this.itemQueryDataHelpers.setData({ id }, (data) => {
              safeAssign(data, "userData", { favorite: false });
            });

            yield* service.markItemUnFavorite(id).pipe(
              Effect.catchTag("MutationError", (error) => {
                if (prevData) {
                  this.itemQueryDataHelpers.setData({ id }, prevData);
                }
                return Effect.fail(error);
              })
            );

            yield* Effect.promise(async () => {
              await this.itemQueryDataHelpers.invalidateQuery({ id });
              await onDone?.();
            });
          }.bind(this)
        ),
    }));
}

export type JellyfinCatalogueOperationsType = JellyfinCatalogue;

export const JellyfinCatalogueOperations = new JellyfinCatalogue();

import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client";
import { type RouteSectionProps, useNavigate } from "@solidjs/router";
import { AlertTriangle, ArrowLeft, Eye, EyeOff, RefreshCw } from "lucide-solid";
import { createEffect, onCleanup, Show, splitProps } from "solid-js";
import {
  AutoplayOverlay,
  BufferingIndicator,
  KeyboardShortcutsHelp,
  LoadingSpinner,
  OpenExternalPlayerButton,
  OSD,
  VideoControls,
  VideoInfoOverlay,
  VideoSettingsPanels,
} from "~/components/video";
import { useVideoContext } from "~/contexts/video-context";
import { JellyfinOperations } from "~/effect/services/jellyfin/operations";
import type { WithImage } from "~/effect/services/jellyfin/service";
import { useAutoplay } from "~/hooks/useAutoplay";
import { useVideoKeyboardShortcuts } from "~/hooks/useVideoKeyboardShortcuts";
import { useVideoPlayback } from "~/hooks/useVideoPlayback";
import { useAppPreferences } from "~/lib/store-hooks";
import { commands } from "~/lib/tauri";

export default function Page(props: RouteSectionProps) {
  const [{ params: routeParams }] = splitProps(props, ["params"]);
  const navigate = useNavigate();
  const { store: appPrefs } = useAppPreferences();

  const itemDetails = JellyfinOperations.getItem(
    () => routeParams.id,
    {
      fields: ["Overview", "ParentId"],
    },
    () => ({
      enabled: !!routeParams.id,
      refetchOnWindowFocus: false,
      refetchOnReconnect: false,
    })
  );

  const seriesDetails = JellyfinOperations.getItem(
    () => itemDetails.data?.SeriesId as string,
    {
      fields: ["ParentId"],
    },
    () => ({
      enabled:
        !!itemDetails.data?.SeriesId && itemDetails.data?.Type === "Episode",
      refetchOnWindowFocus: false,
    })
  );

  // Use the custom hook for playback state management
  const {
    state,
    setState,
    openPanel,
    setOpenPanel,
    showControls,
    toggleControlsLock,
    togglePlay,
    toggleMute,
    handleVolumeChange,
    setSpeed,
    handleProgressClick,
    handleOpenPip,
    handleControlMouseEnter,
    handleControlMouseLeave,
    handleControlInteractionStart,
    navigateToChapter,
    showOSD,
    hideOSD,
    toggleHelp,
    retryPlayback,
    onEndOfFile,
    resetTransientUiState,
    selectAudioTrack,
    selectSubtitleTrack,
  } = useVideoPlayback(
    () => routeParams.id,
    () => itemDetails.data
  );

  const [videoContext] = useVideoContext();

  const exitPlayer = () => {
    resetTransientUiState();
    if (!videoContext.isPip) {
      commands.playbackClear();
    }
    navigate(-1);
  };

  onCleanup(() => {
    resetTransientUiState();
  });

  // Use autoplay hook - don't destructure to maintain reactivity
  const autoplayHook = useAutoplay({
    currentItem: () => itemDetails.data,
    onEndOfFile,
    playbackState: {
      currentTime: () => state.currentTime,
      duration: () => state.duration,
      paused: () => !state.playing,
    },
  });

  let audioBtnRef!: HTMLButtonElement;
  let subsBtnRef!: HTMLButtonElement;
  let speedBtnRef!: HTMLButtonElement;
  let panelRef!: HTMLDivElement;
  const setPanelRef = (el: HTMLDivElement) => {
    panelRef = el;
  };

  // Use keyboard shortcuts hook
  useVideoKeyboardShortcuts({
    state,
    openPanel,
    setOpenPanel,
    togglePlay,
    toggleMute,
    handleVolumeChange,
    setSpeed,
    showControls,
    navigateToChapter,
    toggleHelp,
    isHelpOpen: () => state.showHelp,
    showOSD,
    handleOpenPip,
    selectAudioTrack,
    selectSubtitleTrack,
  });

  // Close panel when clicking outside
  createEffect(() => {
    const onDown = (e: MouseEvent) => {
      if (!panelRef) {
        return;
      }
      const t = e.target as Node;
      if (panelRef.contains(t)) {
        return;
      }
      if (audioBtnRef?.contains(t)) {
        return;
      }
      if (subsBtnRef?.contains(t)) {
        return;
      }
      if (speedBtnRef?.contains(t)) {
        return;
      }
      setOpenPanel(null);
    };
    document.addEventListener("mousedown", onDown);
    onCleanup(() => document.removeEventListener("mousedown", onDown));
  });

  // Ctrl+scroll for volume control
  createEffect(() => {
    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey) {
        e.preventDefault();
        const delta = e.deltaY > 0 ? -5 : 5;
        const newVolume = Math.max(0, Math.min(200, state.volume + delta));
        handleVolumeChange(newVolume);
        showControls();
      }
    };
    document.addEventListener("wheel", handleWheel, { passive: false });
    onCleanup(() => document.removeEventListener("wheel", handleWheel));
  });

  const isInsideControlSurface = (target: EventTarget | null) => {
    if (!(target instanceof Element)) {
      return false;
    }

    return (
      panelRef?.contains(target) ||
      audioBtnRef?.contains(target) ||
      subsBtnRef?.contains(target) ||
      speedBtnRef?.contains(target) ||
      target.classList.contains("control-element") ||
      !!target.closest(".control-element")
    );
  };

  const handleMouseMove = (e: MouseEvent) => {
    if (state.controlsLocked) {
      return;
    }

    if (isInsideControlSurface(e.target)) {
      handleControlMouseEnter();
      return;
    }

    handleControlMouseLeave();
    showControls();
  };

  const handlePointerDown = (e: PointerEvent) => {
    if (isInsideControlSurface(e.target)) {
      handleControlInteractionStart();
    }
  };

  const handleWindowClick = (e: MouseEvent) => {
    const target = e.target;
    // Ignore clicks inside any control surface
    if (isInsideControlSurface(target)) {
      return;
    }

    if (state.showControls) {
      setState("showControls", false);
      commands.toggleTitlebarHide(true);
    } else {
      showControls();
    }
  };

  return (
    <div
      class="dark relative flex h-full w-full flex-col gap-2 overflow-hidden bg-transparent"
      onClick={handleWindowClick}
      onMouseMove={handleMouseMove}
      onPointerDown={handlePointerDown}
      role="button"
    >
      {/* ── Initial Loading Overlay ── */}
      <Show when={state.isLoading}>
        <div class="absolute inset-0 z-50 flex items-center justify-center bg-[#080c16]/95 backdrop-blur-[2px]">
          <div class="flex flex-col items-center gap-5">
            <LoadingSpinner
              loadingStage={state.loadingStage}
              progress={state.bufferingPercentage}
              size="lg"
              text="Loading video…"
            />
            <Show when={state.bufferingPercentage > 0}>
              {/* Blue progress bar */}
              <div class="h-[2px] w-44 overflow-hidden rounded-full bg-white/[0.08]">
                <div
                  class="h-full rounded-full bg-blue-400/70 transition-[width] duration-500"
                  style={{ width: `${state.bufferingPercentage}%` }}
                />
              </div>
              <span class="font-mono text-[11px] text-white/30 tabular-nums">
                {Math.round(state.bufferingPercentage)}%
              </span>
            </Show>
          </div>
        </div>
      </Show>

      {/* ── Buffering Overlay — only when not initial loading ── */}
      <Show
        when={state.isBuffering && !state.isLoading && !state.playbackError}
      >
        <BufferingIndicator
          bufferHealth={state.bufferHealth}
          bufferingPercentage={state.bufferingPercentage}
          isBuffering={state.isBuffering}
          networkQuality={state.networkQuality}
          showText
          variant="overlay"
        />
      </Show>

      {/* ── Playback Error Overlay ── */}
      <Show when={state.playbackError}>
        <div class="absolute inset-0 z-50 flex items-center justify-center bg-[#080c16]/85 backdrop-blur-sm">
          <div class="flex max-w-sm flex-col items-center gap-5 rounded-2xl border border-white/[0.08] bg-[#0d1220]/95 px-8 py-7 shadow-[0_24px_64px_rgba(0,0,0,0.8)]">
            <div class="flex h-14 w-14 items-center justify-center rounded-2xl bg-red-500/[0.12] ring-1 ring-red-500/25">
              <AlertTriangle class="h-6 w-6 text-red-400" />
            </div>
            <div class="text-center">
              <p class="font-semibold text-base text-white tracking-tight">
                Playback failed
              </p>
              <p class="mt-1.5 line-clamp-3 text-[13px] text-white/50 leading-relaxed">
                {state.playbackError}
              </p>
            </div>
            <div class="flex w-full gap-2.5">
              <button
                class="flex flex-1 items-center justify-center gap-1.5 rounded-xl bg-white px-4 py-2.5 font-semibold text-black text-sm transition-opacity duration-150 hover:opacity-90 active:scale-[0.97]"
                onClick={(e) => {
                  e.stopPropagation();
                  retryPlayback();
                }}
              >
                <RefreshCw class="h-3.5 w-3.5" />
                Retry
              </button>
              <button
                class="flex flex-1 items-center justify-center gap-1.5 rounded-xl border border-white/[0.12] bg-white/[0.05] px-4 py-2.5 font-medium text-sm text-white/65 transition-colors duration-150 hover:bg-white/[0.1] hover:text-white active:scale-[0.97]"
                onClick={(e) => {
                  e.stopPropagation();
                  exitPlayer();
                }}
              >
                Go back
              </button>
            </div>
          </div>
        </div>
      </Show>

      {/* ── Lock Button — always visible ── */}
      <button
        aria-label={
          state.controlsLocked ? "Unlock controls" : "Lock controls hidden"
        }
        class="control-element fixed top-6 right-4 z-50 rounded-full bg-[#0d1220]/70 p-2.5 text-white/70 shadow-[0_4px_16px_rgba(0,0,0,0.4)] ring-1 ring-white/[0.06] ring-inset transition-all duration-150 hover:bg-[#0d1220]/90 hover:text-white"
        onClick={(e) => {
          e.stopPropagation();
          toggleControlsLock();
        }}
      >
        <Show
          fallback={<Eye class="h-[18px] w-[18px]" />}
          when={state.controlsLocked}
        >
          <EyeOff class="h-[18px] w-[18px]" />
        </Show>
      </button>

      <Show when={state.showControls}>
        {/* ── Item Info Overlay ── */}
        <VideoInfoOverlay
          isStale={itemDetails.data?.Id !== routeParams.id}
          itemDetails={itemDetails}
          seriesDetails={seriesDetails}
        />

        {/* ── Bottom Controls ── */}
        <div
          class="control-element pointer-events-none fixed right-0 bottom-0 left-0 p-4"
          onClick={(e) => e.stopPropagation()}
          onMouseEnter={(e) => {
            e.stopPropagation();
            handleControlMouseEnter();
          }}
          onMouseLeave={(e) => {
            e.stopPropagation();
            handleControlMouseLeave();
          }}
          role="group"
        >
          {/* Soft vignette gradient behind controls — deep navy */}
          <div class="pointer-events-none absolute right-0 bottom-0 left-0 h-60 bg-gradient-to-t from-[#080c16]/90 via-[#080c16]/30 to-transparent" />

          <div class="pointer-events-auto relative mx-auto flex w-full max-w-4xl flex-col gap-2.5">
            {/* Dropdown Panels */}
            <VideoSettingsPanels
              onNavigateToChapter={navigateToChapter}
              onSelectAudioTrack={selectAudioTrack}
              onSelectSubtitleTrack={selectSubtitleTrack}
              openPanel={openPanel()}
              panelRef={setPanelRef}
              setOpenPanel={setOpenPanel}
              setState={setState}
              state={state}
            />

            {/* Main Control Bar */}
            <VideoControls
              audioBtnRef={audioBtnRef}
              isPip={videoContext.isPip}
              onNavigateToChapter={navigateToChapter}
              onOpenPip={handleOpenPip}
              onProgressClick={handleProgressClick}
              onSetSpeed={setSpeed}
              onToggleMute={toggleMute}
              onTogglePlay={togglePlay}
              onVolumeChange={handleVolumeChange}
              openPanel={openPanel}
              setOpenPanel={setOpenPanel}
              speedBtnRef={speedBtnRef}
              state={state}
              subsBtnRef={subsBtnRef}
            />
          </div>
        </div>

        {/* ── Back Button ── */}
        <button
          class="control-element fixed top-6 left-4 z-50 rounded-full bg-[#0d1220]/70 p-2.5 text-white/70 shadow-[0_4px_16px_rgba(0,0,0,0.4)] ring-1 ring-white/[0.06] ring-inset transition-all duration-150 hover:bg-[#0d1220]/90 hover:text-white"
          onClick={(e) => {
            e.stopPropagation();
            exitPlayer();
          }}
        >
          <ArrowLeft class="h-[18px] w-[18px]" />
        </button>

        {/* ── External Player Button ── */}
        <Show when={state.url.length}>
          <div class="control-element fixed top-8 right-20 z-50">
            <OpenExternalPlayerButton
              beforePlaying={() => {
                commands.playbackPause();
              }}
              player={appPrefs.externalPlayer}
              url={state.url}
            />
          </div>
        </Show>
      </Show>

      {/* ── Autoplay Overlay ── */}
      <Show when={autoplayHook().nextEpisode}>
        <div class="control-element">
          <AutoplayOverlay
            isCollapsed={autoplayHook().isCollapsed()}
            isVisible={autoplayHook().showAutoplay()}
            nextEpisode={autoplayHook().nextEpisode as WithImage<BaseItemDto>}
            onCancel={autoplayHook().cancelAutoplay}
            onPlayNext={() => {
              autoplayHook().playNextEpisode();
            }}
            setIsCollapsed={autoplayHook().setIsCollapsed}
          />
        </div>
      </Show>

      {/* ── OSD (On-Screen Display) ── */}
      <OSD onHide={hideOSD} state={state.osd} />

      {/* ── Keyboard Shortcuts Help ── */}
      <KeyboardShortcutsHelp onClose={toggleHelp} visible={state.showHelp} />
    </div>
  );
}

import {
  type BaseItemDto,
  PlayMethod,
} from "@jellyfin/sdk/lib/generated-client";
import { getPlaystateApi } from "@jellyfin/sdk/lib/utils/api/playstate-api";
import type { UnlistenFn } from "@tauri-apps/api/event";
import { getAllWindows, getCurrentWindow } from "@tauri-apps/api/window";
import { Effect } from "effect";
import { createEffect, createSignal, onCleanup } from "solid-js";
import { createStore } from "solid-js/store";
import type {
  BufferHealth,
  Chapter,
  LoadingStage,
  NetworkQuality,
  OpenPanel,
  OSDState,
  Track,
} from "~/components/video/types";
import { useVideoContext } from "~/contexts/video-context";
import { useRuntime } from "~/effect/runtime/use-runtime";
import { AuthService } from "~/effect/services/auth";
import type { WithImage } from "~/effect/services/jellyfin/service";
import {
  findTrackByLanguage,
  normalizeLanguageCode,
  resolveLanguagePreferences,
  SUBTITLE_OFF,
} from "~/lib/playback-language-preferences";
import { useAppPreferences } from "~/lib/store-hooks";
import { commands, events } from "~/lib/tauri";
import { planPlaybackSessionTeardown } from "~/playback/playback-session-lifecycle";

type ItemDetails = WithImage<BaseItemDto> | undefined;

/**
 * Returns true only when `url` is a canonical Jellyfin subtitle stream URL
 * for the given item/mediaSource, i.e. it matches:
 *   /Videos/{itemId}/{mediaSourceId}/Subtitles/{index}/Stream.{ext}
 * A loose `/Subtitles/` check could accept unrelated or filesystem-backed
 * URLs that mpv cannot fetch directly.
 */
function isCanonicalSubtitleStreamUrl(
  url: string,
  itemId: string,
  mediaSourceId: string
): boolean {
  if (!url) {
    return false;
  }
  if (!itemId) {
    return false;
  }
  if (!mediaSourceId) {
    return false;
  }
  // Escape special regex chars in the dynamic segments.
  const escId = itemId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const escSrc = mediaSourceId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(
    `/Videos/${escId}/${escSrc}/Subtitles/\\d+/Stream\\.[^/?#]+`,
    "i"
  );
  return re.test(url);
}

/**
 * Returns a copy of `url` with sensitive query parameters redacted for safe
 * diagnostic logging.  Currently redacts `api_key`; the path and all other
 * query params are preserved so logs remain useful.
 */
function redactUrlForLog(url: string): string {
  try {
    const parsed = new URL(url);
    if (parsed.searchParams.has("api_key")) {
      parsed.searchParams.set("api_key", "[REDACTED]");
    }
    return parsed.toString();
  } catch {
    // Not a valid absolute URL – return as-is (no sensitive param expected).
    return url;
  }
}

export function useVideoPlayback(
  itemId: () => string,
  itemDetails: () => ItemDetails
) {
  const runtime = useRuntime();
  const jf = runtime.runSync(
    Effect.gen(function* () {
      const auth = yield* AuthService;
      const api = yield* auth.getApi();
      const user = yield* auth.getUser();
      return { api, userId: user.Id };
    })
  );

  const { store: appPrefs, setStore: setAppPrefs } = useAppPreferences();

  /**
   * Returns the SeriesId when the current item is an episode, else undefined.
   * Only returns a value when `itemDetails()` actually corresponds to the
   * active playback item, preventing stale metadata during fast transitions.
   */
  const getSeriesId = (): string | undefined => {
    const details = itemDetails();
    if (!details?.Id || details.Id !== state.currentItemId) {
      return;
    }
    if (details.Type === "Episode" && details.SeriesId) {
      return details.SeriesId;
    }
  };

  /** Persist a per-series language override (episodes only).
   *  If metadata isn't current yet, queue the save for later. */
  const saveSeriesOverride = (
    field: "audioLanguage" | "subtitleLanguage",
    value: string
  ) => {
    if (!isMetadataCurrent()) {
      // Queue the save – it will be flushed when metadata arrives
      pendingSeriesSaves.push({
        field,
        value,
        forItemId: state.currentItemId,
      });
      return;
    }
    const seriesId = getSeriesId();
    if (!seriesId) {
      return;
    }
    const existing = appPrefs.seriesLanguageOverrides[seriesId] ?? {};
    setAppPrefs("seriesLanguageOverrides", seriesId, {
      ...existing,
      [field]: value,
    });
  };

  /**
   * Centralized manual audio-track selection.
   * Used by both panel click-handlers and keyboard shortcuts.
   */
  const selectAudioTrack = async (track: Track) => {
    audioIsManual = true;
    await commands.playbackChangeAudio(track.id.toString());
    setState("audioIndex", track.id);
    // Persist per-series override when the track has a language code
    const lang = normalizeLanguageCode(track.lang);
    if (lang) {
      saveSeriesOverride("audioLanguage", lang);
    }
  };

  /**
   * Centralized manual subtitle-track selection.
   * Pass null (or a track with id 0) to turn subtitles off.
   */
  const selectSubtitleTrack = async (track: Track | null) => {
    if (!track || track.id === 0) {
      subtitleIsManual = true;
      await commands.playbackChangeSubtitle("0");
      setState("subtitleIndex", 0);
      saveSeriesOverride("subtitleLanguage", SUBTITLE_OFF);
      return;
    }
    subtitleIsManual = true;
    await commands.playbackChangeSubtitle(track.id.toString());
    setState("subtitleIndex", track.id);
    const lang = normalizeLanguageCode(track.lang);
    if (lang) {
      saveSeriesOverride("subtitleLanguage", lang);
    }
  };

  const [videoContext, setVideoState] = useVideoContext();
  const playbackSessionId = crypto.randomUUID();
  setVideoState("activePlaybackSessionId", playbackSessionId);

  const [state, setState] = createStore({
    audioIndex: -1,
    subtitleIndex: -1,
    currentTime: "",
    playing: true,
    volume: 100,
    isMuted: false,
    playbackSpeed: 1,
    audioList: [] as Track[],
    subtitleList: [] as Track[],
    chapters: [] as Chapter[],
    duration: 0,
    showControls: true,
    controlsLocked: false,
    url: "",
    currentItemId: itemId(),
    isHoveringControls: false,
    isInteractingControls: false,
    // New buffering and loading states
    bufferedTime: 0,
    bufferingPercentage: 0,
    isLoading: true,
    isBuffering: false,
    isSeeking: false,
    playbackError: null as string | null,
    // OSD and help states
    osd: {
      visible: false,
      type: "play" as const,
      value: null,
      icon: "Play",
      label: "",
    } as OSDState,
    showHelp: false,
    loadingStage: "connecting" as LoadingStage,
    networkQuality: "good" as NetworkQuality,
    bufferHealth: "healthy" as BufferHealth,
  });

  const [openPanel, setOpenPanel] = createSignal<OpenPanel>(null);
  const [hideControlsTimeout, setHideControlsTimeout] =
    createSignal<NodeJS.Timeout>();

  let unlistenFuncs: UnlistenFn[] = [];
  let listenerSetupVersion = 0;
  let seekGuardTimeout: NodeJS.Timeout | undefined;
  let bufferingResetTimeout: NodeJS.Timeout | undefined;
  let localSeekTarget: number | null = null;
  let localSeekGuardUntil = 0;
  let hasClearedPlayback = false;
  let lastConfirmedPlaybackProgressAt = 0;
  let pausedForCache = false;
  let lastWrittenTime = 0; // last parsedTime written to store
  const TIME_WRITE_THRESHOLD = 0.25; // seconds – coalesce smaller deltas

  const removeControlInteractionListeners = () => {
    window.removeEventListener("pointerup", handleControlInteractionEnd);
    window.removeEventListener("pointercancel", handleControlInteractionEnd);
  };

  const SEEK_GUARD_MS = 900;
  const SEEK_CONFIRM_TOLERANCE_SECONDS = 1.5;
  const BUFFERING_PROGRESS_GRACE_MS = 1500;

  // Jellyfin playback reporting
  const playSessionId = crypto.randomUUID();
  let lastProgressReportTime = 0;

  const shouldPreventControlsAutoHide = () =>
    state.controlsLocked ||
    state.isHoveringControls ||
    state.isInteractingControls;

  const hasRecentPlaybackProgress = () =>
    Date.now() - lastConfirmedPlaybackProgressAt < BUFFERING_PROGRESS_GRACE_MS;

  const clearHideControlsTimeout = () => {
    const existing = hideControlsTimeout();
    if (existing) {
      clearTimeout(existing);
      setHideControlsTimeout(undefined);
    }
  };

  const scheduleHideControls = () => {
    clearHideControlsTimeout();

    if (shouldPreventControlsAutoHide()) {
      return;
    }

    const timeout = setTimeout(() => {
      if (shouldPreventControlsAutoHide()) {
        return;
      }

      setState("showControls", false);
      commands.toggleTitlebarHide(true);
      setHideControlsTimeout(undefined);
    }, 1000);

    setHideControlsTimeout(timeout);
  };

  const showControls = () => {
    if (state.controlsLocked) {
      return;
    }
    setState("showControls", true);
    commands.toggleTitlebarHide(false);
    scheduleHideControls();
  };

  const toggleControlsLock = () => {
    const nextLocked = !state.controlsLocked;
    setState("controlsLocked", nextLocked);

    if (nextLocked) {
      // When locking, hide controls immediately
      setState("showControls", false);
      commands.toggleTitlebarHide(true);
      clearHideControlsTimeout();
    } else {
      // When unlocking, show controls immediately
      setState("showControls", true);
      commands.toggleTitlebarHide(false);
      scheduleHideControls();
    }
  };

  const showOSD = (
    type: OSDState["type"],
    value: string | number | null,
    label?: string
  ) => {
    setState("osd", {
      visible: true,
      type,
      value,
      icon: type,
      label: label || "",
    });
  };

  const hideOSD = () => {
    setState("osd", "visible", false);
  };

  const toggleHelp = () => {
    setState("showHelp", !state.showHelp);
  };

  const updateLoadingStage = (stage: LoadingStage) => {
    setState("loadingStage", stage);
  };

  const updateNetworkQuality = (quality: NetworkQuality) => {
    setState("networkQuality", quality);
  };

  const updateBufferHealth = (health: BufferHealth) => {
    setState("bufferHealth", health);
  };

  const setBufferingState = (next: boolean, debounceMs = 250) => {
    if (next) {
      clearTimeout(bufferingResetTimeout);
      if (!state.isBuffering) {
        setState("isBuffering", true);
      }
      return;
    }

    clearTimeout(bufferingResetTimeout);
    bufferingResetTimeout = setTimeout(() => {
      if (state.isBuffering) {
        setState("isBuffering", false);
      }
    }, debounceMs);
  };

  const beginAbsoluteSeek = (targetSeconds: number) => {
    const safeTarget = Math.max(
      0,
      Math.min(
        targetSeconds,
        state.duration > 0 ? state.duration : Number.POSITIVE_INFINITY
      )
    );

    localSeekTarget = safeTarget;
    localSeekGuardUntil = Date.now() + SEEK_GUARD_MS;

    clearTimeout(seekGuardTimeout);
    seekGuardTimeout = setTimeout(() => {
      localSeekTarget = null;
      localSeekGuardUntil = 0;
      setState("isSeeking", false);
    }, SEEK_GUARD_MS + 300);

    setState("isSeeking", true);
    showControls();
    commands.playbackAbsoluteSeek(safeTarget);
  };

  const clearPlaybackError = () => {
    setState("playbackError", null);
  };

  const clearPlaybackIfActiveSession = async () => {
    if (hasClearedPlayback) {
      return;
    }

    const activePlaybackSessionId = videoContext.activePlaybackSessionId;
    if (
      activePlaybackSessionId &&
      activePlaybackSessionId !== playbackSessionId
    ) {
      return;
    }

    hasClearedPlayback = true;
    if (activePlaybackSessionId === playbackSessionId) {
      setVideoState("activePlaybackSessionId", null);
    }
    await commands.playbackClear();
  };

  const retryPlayback = async () => {
    if (!state.url) {
      return;
    }

    clearPlaybackError();
    setState("isLoading", true);
    setBufferingState(false, 0);

    await commands.playbackLoad(state.url);
    await commands.playbackPlay();
  };

  const togglePlay = () => {
    if (state.playing) {
      commands.playbackPause();
      showOSD("pause", null, "Paused");
    } else {
      commands.playbackPlay();
      showOSD("play", null, "Playing");
    }
  };

  const toggleMute = () => {
    if (state.isMuted) {
      const lastVolume = state.volume || 100;
      commands.playbackVolume(lastVolume);
      setState("volume", lastVolume);
      setState("isMuted", false);
      showOSD("unmute", lastVolume, "Unmuted");
    } else {
      commands.playbackVolume(0);
      setState("isMuted", true);
      showOSD("mute", 0, "Muted");
    }
  };

  const handleVolumeChange = (value: number) => {
    const newVolume = Math.round(value);
    commands.playbackVolume(newVolume);
    setState("volume", newVolume);
    setState("isMuted", newVolume === 0);
    showOSD("volume", newVolume);
  };

  const setSpeed = (speed: number) => {
    commands.playbackSpeed(speed);
    setState("playbackSpeed", speed);
    showOSD("speed", speed);
  };

  const navigateToChapter = (chapter: Chapter) => {
    // Convert ticks to seconds (1 tick = 100 nanoseconds = 0.0000001 seconds)
    const startTimeSeconds = chapter.startPositionTicks / 10_000_000;
    beginAbsoluteSeek(startTimeSeconds);
  };

  const handleProgressClick = (value: number) => {
    if (state.duration === 0) {
      return;
    }
    const newTime = (value / 100) * state.duration;
    beginAbsoluteSeek(newTime);
  };

  const syncPipVisibility = async () => {
    const windows = await getAllWindows();
    const pipWindow = windows.find((w) => w.label === "pip");
    const isVisible = (await pipWindow?.isVisible()) ?? false;
    setVideoState("isPip", isVisible);
    return isVisible;
  };

  const getPipToggleLabel = (wasVisible: boolean, isVisible: boolean) => {
    if (wasVisible) {
      return isVisible
        ? "Picture in Picture failed to close"
        : "Picture in Picture closed";
    }

    return isVisible
      ? "Picture in Picture opened"
      : "Picture in Picture failed to open";
  };

  const handleOpenPip = async () => {
    let wasVisible = false;
    let isOpeningPip = false;

    try {
      wasVisible = await syncPipVisibility();

      if (wasVisible) {
        await commands.hidePipWindow();
        const isStillVisible = await syncPipVisibility();
        showOSD(
          "pip",
          null,
          isStillVisible
            ? "Picture in Picture failed to close"
            : "Picture in Picture closed"
        );
        return;
      }

      isOpeningPip = true;
      setVideoState("isPipTransitioning", true);
      await commands.showPipWindow();
      const isVisible = await syncPipVisibility();
      showOSD(
        "pip",
        null,
        isVisible
          ? "Picture in Picture opened"
          : "Picture in Picture failed to open"
      );
    } catch (_error) {
      const isVisible = await syncPipVisibility();
      showOSD("pip", null, getPipToggleLabel(wasVisible, isVisible));
    } finally {
      if (isOpeningPip) {
        setVideoState("isPipTransitioning", false);
      }
    }
  };

  const loadNewVideo = (url: string, newItemId: string) => {
    lastConfirmedPlaybackProgressAt = 0;
    pausedForCache = false;
    setState("url", url);
    setState("currentItemId", newItemId);
    setState("currentTime", "0");
    setState("duration", 0);
    setState("playing", true);
    // Reset track indices so language-preference resolution runs fresh for the new item
    setState("audioIndex", -1);
    setState("subtitleIndex", -1);
    // Clear stale track lists from the previous item
    setState("audioList", []);
    setState("subtitleList", []);
    resetLanguageResolutionState();
    // Reset buffering and loading states for new video
    setState("bufferedTime", 0);
    setState("bufferingPercentage", 0);
    setState("isLoading", true);
    setState("isBuffering", false);
    setState("isSeeking", false);
    setState("playbackError", null);
    commands.playbackLoad(url);
  };

  const handleControlMouseEnter = () => {
    setState("isHoveringControls", true);
    clearHideControlsTimeout();
  };

  const handleControlMouseLeave = () => {
    setState("isHoveringControls", false);
    scheduleHideControls();
  };

  const handleControlInteractionEnd = () => {
    removeControlInteractionListeners();
    setState("isInteractingControls", false);
    scheduleHideControls();
  };

  const handleControlInteractionStart = () => {
    removeControlInteractionListeners();
    setState("isInteractingControls", true);
    setState("showControls", true);
    commands.toggleTitlebarHide(false);
    clearHideControlsTimeout();

    window.addEventListener("pointerup", handleControlInteractionEnd);
    window.addEventListener("pointercancel", handleControlInteractionEnd);
  };

  const resetTransientUiState = () => {
    clearHideControlsTimeout();
    if (openPanel()) {
      setOpenPanel(null);
    }
    setState("showControls", true);
    setState("controlsLocked", false);
    setState("isHoveringControls", false);
    setState("isInteractingControls", false);
    setState("showHelp", false);
    setState("osd", "visible", false);
    setState("isBuffering", false);
    setState("isSeeking", false);
    setState("playbackError", null);
    commands.toggleTitlebarHide(false);
    removeControlInteractionListeners();
  };

  // --- Per-item language-resolution state ---
  // Whether the current audio/subtitle selection was made manually by the user
  // (as opposed to automatic startup resolution).
  let audioIsManual = false;
  let subtitleIsManual = false;
  // Whether automatic startup resolution has been finalized with current metadata
  // (i.e. itemDetails().Id === state.currentItemId).
  let audioStartupFinalized = false;
  let subtitleStartupFinalized = false;
  // Whether external subtitle injection has already been performed for this item.
  let externalSubtitlesLoaded = false;
  // Whether mpv has fired FileLoaded for the current item (guards against pre-load injection).
  // biome-ignore lint/style/useConst: mutated by FileLoaded handler and reset on item change
  let fileLoadedForCurrentItem = false;
  // Queued manual per-series saves to flush once metadata is ready.
  // Each entry records the field, value, and the itemId it was intended for.
  let pendingSeriesSaves: Array<{
    field: "audioLanguage" | "subtitleLanguage";
    value: string;
    forItemId: string;
  }> = [];

  /** Returns true when itemDetails() is loaded and matches the active item. */
  const isMetadataCurrent = (): boolean => {
    const details = itemDetails();
    return !!details?.Id && details.Id === state.currentItemId;
  };

  /** Flush any queued manual per-series saves whose itemId still matches. */
  const flushPendingSeriesSaves = () => {
    const toFlush = pendingSeriesSaves;
    pendingSeriesSaves = [];
    const seriesId = getSeriesId();
    if (!seriesId) {
      return;
    }
    for (const entry of toFlush) {
      if (entry.forItemId !== state.currentItemId) {
        continue;
      }
      const existing = appPrefs.seriesLanguageOverrides[seriesId] ?? {};
      setAppPrefs("seriesLanguageOverrides", seriesId, {
        ...existing,
        [entry.field]: entry.value,
      });
    }
  };

  /** Reset all per-item language resolution flags (call on item change). */
  const resetLanguageResolutionState = () => {
    audioIsManual = false;
    subtitleIsManual = false;
    audioStartupFinalized = false;
    subtitleStartupFinalized = false;
    externalSubtitlesLoaded = false;
    fileLoadedForCurrentItem = false;
    pendingSeriesSaves = [];
  };

  // Persisted per-session media source anchors – set during playback startup
  // and reused for subtitle injection and playback reporting.
  let activeMediaSourceId: string | undefined;
  let activeLiveStreamId: string | undefined;

  let loadVersion = 0;
  createEffect(async () => {
    const currentItemId = itemId();
    const token = jf.api?.accessToken;
    const basePath = jf.api?.basePath;

    if (!(token && jf.api && currentItemId)) {
      return;
    }

    // Prevent reloading if we're already playing the same item
    if (state.currentItemId === currentItemId && state.url) {
      return;
    }

    const thisLoad = ++loadVersion;

    // Reset media-source anchors for this new item before fetching.
    activeMediaSourceId = undefined;
    activeLiveStreamId = undefined;

    lastConfirmedPlaybackProgressAt = 0;
    pausedForCache = false;
    setState("currentItemId", currentItemId);
    setState("currentTime", "0");
    setState("duration", 0);
    setState("playbackError", null);
    // Reset track indices so language-preference resolution runs fresh for the new item
    setState("audioIndex", -1);
    setState("subtitleIndex", -1);
    // Clear stale track lists from the previous item
    setState("audioList", []);
    setState("subtitleList", []);
    resetLanguageResolutionState();

    // Stale-guard helper: returns true when a newer effect run has started,
    // meaning this run must stop issuing player commands immediately.
    const isStale = () => thisLoad !== loadVersion;

    // Fetch playback info to obtain the chosen MediaSourceId (and LiveStreamId)
    // so the video stream URL and subtitle injection both reference the same source.
    let mediaSourceId: string | undefined;
    let liveStreamId: string | undefined;
    try {
      const { getMediaInfoApi } = await import(
        "@jellyfin/sdk/lib/utils/api/media-info-api"
      );
      const res = await getMediaInfoApi(jf.api).getPlaybackInfo({
        itemId: currentItemId,
        userId: jf.userId ?? undefined,
      });
      if (!isStale()) {
        const source = res.data?.MediaSources?.[0];
        mediaSourceId = source?.Id ?? undefined;
        liveStreamId = source?.LiveStreamId ?? undefined;
        activeMediaSourceId = mediaSourceId;
        activeLiveStreamId = liveStreamId;
      }
    } catch (_e) {
      // Playback-info unavailable; fall back to URL without media-source params.
    }

    if (isStale()) {
      return;
    }

    const msParam = mediaSourceId
      ? `&MediaSourceId=${encodeURIComponent(mediaSourceId)}`
      : "";
    const lsParam =
      liveStreamId && mediaSourceId
        ? `&LiveStreamId=${encodeURIComponent(liveStreamId)}`
        : "";
    const url = `${basePath}/Videos/${currentItemId}/Stream?api_key=${token}&container=mp4&static=true${msParam}${lsParam}`;

    setState("url", url);

    // Each step checks staleness *before* sending a command so that a
    // superseded run never issues playbackClear / playbackLoad / playbackPlay
    // after a newer run has already taken ownership of the player.
    if (isStale()) {
      return;
    }
    await commands.playbackClear();

    if (isStale()) {
      return;
    }
    await commands.playbackLoad(url);

    if (isStale()) {
      return;
    }
    await commands.playbackPlay();

    if (isStale()) {
      return;
    }
    setVideoState("pause", false);
  });

  createEffect(() => {
    syncPipVisibility().catch(() => {
      // Do nothing
    });
  });

  createEffect(() => {
    let chapters: Chapter[] = [];

    // Check for chapters in different possible fields
    if (itemDetails()?.Chapters && Array.isArray(itemDetails()?.Chapters)) {
      chapters =
        (itemDetails()?.Chapters?.map((chapter) => ({
          startPositionTicks: chapter?.StartPositionTicks || 0,
          name: chapter?.Name || null,
          imagePath: chapter?.ImagePath || null,
          imageDateModified: chapter?.ImageDateModified || null,
          imageTag: chapter?.ImageTag || null,
        })) as Chapter[]) ?? [];
    }
    setState("chapters", chapters);
  });

  // Re-resolve language preferences and flush queued saves once metadata arrives.
  // This handles the case where track events fired before itemDetails() was current.

  /**
   * Inject external subtitle streams into mpv for the given item details.
   * Called once per playback startup, gated by both `externalSubtitlesLoaded` and
   * `fileLoadedForCurrentItem` so it never fires before mpv has actually loaded the file.
   * The item details object is passed explicitly so the function is not reactive.
   */
  const doInjectExternalSubtitles = async (
    details: NonNullable<ItemDetails>
  ): Promise<void> => {
    if (externalSubtitlesLoaded) {
      return;
    }
    externalSubtitlesLoaded = true;
    const injectionItemId = details.Id;
    if (!jf.api) {
      return;
    }
    if (!jf.userId) {
      return;
    }
    if (!injectionItemId) {
      return;
    }
    try {
      const { getMediaInfoApi } = await import(
        "@jellyfin/sdk/lib/utils/api/media-info-api"
      );
      const res = await getMediaInfoApi(jf.api).getPlaybackInfo({
        itemId: injectionItemId,
        userId: jf.userId,
      });
      // Abort if the active item changed while the request was in-flight.
      if (state.currentItemId !== injectionItemId) {
        return;
      }
      // Prefer the media source whose Id matches the one chosen during
      // playback startup (activeMediaSourceId).  Fall back to index 0 only
      // when no anchor is available so that the previous behaviour is
      // preserved for edge cases where playback-info was unavailable.
      const sources = res.data?.MediaSources ?? [];
      const activeSource =
        (activeMediaSourceId
          ? sources.find((s) => s.Id === activeMediaSourceId)
          : undefined) ?? sources[0];
      const basePath = jf.api.basePath ?? "";
      const token = jf.api.accessToken ?? "";
      const subtitleSourceId =
        activeSource?.Id ?? activeMediaSourceId ?? "";
      for (const stream of activeSource?.MediaStreams ?? []) {
        if (stream.Type !== "Subtitle" || !stream.IsExternal) {
          continue;
        }
        // Use DeliveryUrl only when it is a canonical Jellyfin subtitle
        // stream URL for the active item/mediaSource.  Loose checks (e.g.
        // just looking for "/Subtitles/" anywhere) could accept
        // filesystem-backed or unrelated URLs that mpv cannot fetch.
        const deliveryUrl = (stream as { DeliveryUrl?: string }).DeliveryUrl;
        const useDeliveryUrl =
          typeof deliveryUrl === "string" &&
          isCanonicalSubtitleStreamUrl(
            deliveryUrl,
            details.Id ?? "",
            subtitleSourceId
          );
        let url: string;
        if (useDeliveryUrl && typeof deliveryUrl === "string") {
          url = deliveryUrl.startsWith("/")
            ? `${basePath}${deliveryUrl}`
            : deliveryUrl;
        } else {
          if (stream.Index == null || !subtitleSourceId || !details.Id) {
            continue;
          }
          const SUBTITLE_CODEC_TO_EXT: Record<string, string> = {
            subrip: "srt",
            webvtt: "vtt",
            srt: "srt",
            vtt: "vtt",
            ass: "ass",
            ssa: "ssa",
            pgs: "sup",
            dvd_subtitle: "sub",
            hdmv_pgs_subtitle: "sup",
          };
          const codec = stream.Codec ?? "srt";
          const format = SUBTITLE_CODEC_TO_EXT[codec.toLowerCase()] ?? codec;
          url = `${basePath}/Videos/${details.Id}/${subtitleSourceId}/Subtitles/${stream.Index}/Stream.${format}?api_key=${token}`;
        }
        // Re-check staleness before each individual sub-add command.
        if (state.currentItemId !== injectionItemId) {
          break;
        }

        // Build a human-friendly track title for the subtitle dropdown.
        // Prefer DisplayTitle (e.g. "English (SRT)"), fall back to Language, then Title.
        const subtitleTitle: string | null =
          (stream as { DisplayTitle?: string }).DisplayTitle ||
          stream.Language ||
          stream.Title ||
          null;
        const subtitleLang: string | null = stream.Language || null;

        // --- Diagnostics: log context for every attempted subtitle load ---
        const diagCodec = stream.Codec ?? "unknown";
        const subtitleIndex = stream.Index ?? -1;
        const urlSource = useDeliveryUrl ? "DeliveryUrl" : "constructed";
        // biome-ignore lint/suspicious/noConsole: subtitle diagnostics
        console.debug(
          "[subtitle-inject] itemId=%s mediaSourceId=%s index=%d codec=%s source=%s title=%s lang=%s url=%s",
          injectionItemId,
          subtitleSourceId,
          subtitleIndex,
          diagCodec,
          urlSource,
          subtitleTitle ?? "(none)",
          subtitleLang ?? "(none)",
          redactUrlForLog(url)
        );

        // Lightweight app-side reachability check (HEAD, fallback GET).
        // Diagnostics only – a failing check does NOT prevent the load.
        // A 5-second timeout prevents a slow/hanging URL from delaying
        // the subsequent playbackLoadSubtitle call beyond a short bound.
        try {
          const validationAbort = new AbortController();
          const validationTimeout = setTimeout(
            () => validationAbort.abort(),
            5000
          );
          let validationRes: Response;
          try {
            validationRes = await fetch(url, {
              method: "HEAD",
              // Credentials are embedded in the URL via api_key; no cookies needed.
              credentials: "omit",
              signal: validationAbort.signal,
            });
            // Some servers don't support HEAD; retry with GET + short range.
            if (
              validationRes.status === 405 ||
              validationRes.status === 501
            ) {
              validationRes = await fetch(url, {
                method: "GET",
                headers: { Range: "bytes=0-0" },
                credentials: "omit",
                signal: validationAbort.signal,
              });
            }
          } finally {
            clearTimeout(validationTimeout);
          }
          if (!validationRes.ok && validationRes.status !== 206) {
            // biome-ignore lint/suspicious/noConsole: subtitle diagnostics
            console.warn(
              "[subtitle-inject] Validation failed: itemId=%s index=%d status=%d url=%s",
              injectionItemId,
              subtitleIndex,
              validationRes.status,
              redactUrlForLog(url)
            );
          }
        } catch (validationErr) {
          // biome-ignore lint/suspicious/noConsole: subtitle diagnostics
          console.warn(
            "[subtitle-inject] Validation error: itemId=%s index=%d err=%s url=%s",
            injectionItemId,
            subtitleIndex,
            validationErr instanceof Error
              ? validationErr.message
              : String(validationErr),
            redactUrlForLog(url)
          );
        }

        try {
          await commands.playbackLoadSubtitle(url, subtitleTitle, subtitleLang);
        } catch (_e) {
          // Skip – mpv may reject unsupported formats or stale URLs.
        }
      }
    } catch (_e) {
      // Playback info fetch failed; external subtitles unavailable.
    }
  };

  createEffect(async () => {
    const details = itemDetails();
    if (!details?.Id || details.Id !== state.currentItemId) {
      return;
    }

    // Flush any queued manual per-series saves now that we know the series.
    flushPendingSeriesSaves();

    // Re-resolve audio startup if it wasn't finalized with current metadata
    // and the user hasn't manually changed it.
    if (
      !(audioStartupFinalized || audioIsManual) &&
      state.audioList.length > 0
    ) {
      const resolved = resolveLanguagePreferences(appPrefs, getSeriesId());
      const preferred = findTrackByLanguage(
        state.audioList,
        resolved.audioLanguage
      );
      if (preferred) {
        await commands.playbackChangeAudio(preferred.id.toString());
        setState("audioIndex", preferred.id as number);
      }
      audioStartupFinalized = true;
    }

    // Re-resolve subtitle startup if it wasn't finalized with current metadata
    // and the user hasn't manually changed it.
    if (
      !(subtitleStartupFinalized || subtitleIsManual) &&
      state.subtitleList.length > 0
    ) {
      const resolved = resolveLanguagePreferences(appPrefs, getSeriesId());
      if (resolved.subtitleLanguage === SUBTITLE_OFF) {
        await commands.playbackChangeSubtitle("0");
        setState("subtitleIndex", 0);
      } else {
        const preferred = findTrackByLanguage(
          state.subtitleList,
          resolved.subtitleLanguage
        );
        if (preferred) {
          await commands.playbackChangeSubtitle(preferred.id.toString());
          setState("subtitleIndex", preferred.id);
        }
      }
      subtitleStartupFinalized = true;
    }

    // Inject external subtitle tracks into mpv once per item startup, but only
    // after mpv has confirmed the file is loaded (fileLoadedForCurrentItem).
    // This avoids a startup race where sub-add is issued before mpv is ready.
    if (!externalSubtitlesLoaded && fileLoadedForCurrentItem) {
      await doInjectExternalSubtitles(details);
    }
  });

  createEffect(async () => {
    const setupVersion = ++listenerSetupVersion;
    const nextUnlistenFuncs: UnlistenFn[] = [];
    const registerListener = async (
      listenerPromise: Promise<UnlistenFn>
    ): Promise<boolean> => {
      const unlisten = await listenerPromise;
      if (setupVersion !== listenerSetupVersion) {
        unlisten();
        return false;
      }
      nextUnlistenFuncs.push(unlisten);
      return true;
    };

    const currentItemId = itemId();
    // Clean up existing listeners when itemId changes
    unlistenFuncs.forEach((unlisten) => {
      unlisten();
    });
    unlistenFuncs = [];

    if (
      !(await registerListener(
        events.fileLoadedChange.listen(async ({ payload }) => {
          // Reset loading state when file is loaded
          setState("isLoading", false);
          setBufferingState(false, 0);
          clearPlaybackError();
          commands.playbackPlay();
          setVideoState("pause", false);

          const currentTime = payload.current_time;
          const duration = payload.duration;
          setState("duration", duration);

          // Mark that mpv has loaded the file for the current item.
          // This unblocks external subtitle injection which must not happen
          // before the file is ready (race condition otherwise).
          fileLoadedForCurrentItem = true;
          // If item metadata is already available, inject external subtitles now.
          // Otherwise the createEffect watching itemDetails() will trigger once
          // metadata arrives and fileLoadedForCurrentItem is already true.
          const loadedDetails = itemDetails();
          if (
            loadedDetails?.Id &&
            loadedDetails.Id === state.currentItemId &&
            !externalSubtitlesLoaded
          ) {
            // Fire-and-forget; errors are caught inside doInjectExternalSubtitles.
            doInjectExternalSubtitles(loadedDetails).catch((_e) => {
              // Subtitle injection errors are non-fatal.
            });
          }

          if (Number(state.currentTime) > 0) {
            beginAbsoluteSeek(Number(state.currentTime));
          } else {
            const userProgress = itemDetails()?.UserData?.PlaybackPositionTicks
              ? (itemDetails()?.UserData?.PlaybackPositionTicks as number) /
                10_000_000
              : 0;

            if (userProgress > 0 && userProgress !== Number(currentTime)) {
              beginAbsoluteSeek(userProgress);
            }
          }

          try {
            if (!jf.api) {
              return;
            }
            const playstateApi = getPlaystateApi(jf.api);
            await playstateApi.reportPlaybackStart({
              playbackStartInfo: {
                ItemId: currentItemId,
                PlaySessionId: playSessionId,
                MediaSourceId: activeMediaSourceId,
                LiveStreamId: activeLiveStreamId,
                CanSeek: true,
                IsPaused: false,
                IsMuted: state.isMuted,
                VolumeLevel: Math.min(state.volume, 100), // Clamp to 100 for Jellyfin
                PlayMethod: PlayMethod.DirectStream,
                AudioStreamIndex:
                  state.audioIndex >= 0 ? state.audioIndex : undefined,
                SubtitleStreamIndex:
                  state.subtitleIndex > 0 ? state.subtitleIndex : undefined,
              },
            });

            // Initialize last progress report time
            lastProgressReportTime = Date.now();
          } catch (_error) {
            // Do nothing
          }
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.playBackTimeChange.listen(async ({ payload }) => {
          const newTime = payload.position;
          const parsedTime = Number(newTime);

          if (Number.isNaN(parsedTime)) {
            return;
          }

          const now = Date.now();
          if (
            localSeekTarget !== null &&
            now <= localSeekGuardUntil &&
            Math.abs(parsedTime - localSeekTarget) >
              SEEK_CONFIRM_TOLERANCE_SECONDS
          ) {
            return;
          }

          const previousTime = Number(state.currentTime);
          const hasPlaybackProgress =
            Number.isNaN(previousTime) ||
            Math.abs(parsedTime - previousTime) > 0.01;

          if (localSeekTarget !== null) {
            const matchedSeek =
              Math.abs(parsedTime - localSeekTarget) <=
              SEEK_CONFIRM_TOLERANCE_SECONDS;
            const seekGuardExpired = now > localSeekGuardUntil;
            if (matchedSeek || seekGuardExpired) {
              localSeekTarget = null;
              localSeekGuardUntil = 0;
            }
          }

          if (hasPlaybackProgress) {
            lastConfirmedPlaybackProgressAt = now;
          }

          // Only write currentTime to store when the delta is meaningful
          // to reduce reactive re-renders on high-frequency events.
          const timeDelta = Math.abs(parsedTime - lastWrittenTime);
          const seekJustConfirmed = localSeekTarget === null && state.isSeeking;
          if (
            timeDelta >= TIME_WRITE_THRESHOLD ||
            seekJustConfirmed ||
            state.isLoading
          ) {
            lastWrittenTime = parsedTime;
            setState({
              currentTime: newTime,
              isLoading: false,
              isSeeking: false,
            });
          } else {
            // Still clear transient flags even when skipping time write
            if (state.isLoading) {
              setState("isLoading", false);
            }
            if (state.isSeeking) {
              setState("isSeeking", false);
            }
          }

          if (state.playing && hasPlaybackProgress) {
            pausedForCache = false;
            setBufferingState(false, 0);
          }

          // Report progress to Jellyfin every 3 seconds
          if (now - lastProgressReportTime >= 3000 && jf.api) {
            lastProgressReportTime = now;
            try {
              const playstateApi = getPlaystateApi(jf.api);
              await playstateApi.reportPlaybackProgress({
                playbackProgressInfo: {
                  ItemId: currentItemId,
                  PlaySessionId: playSessionId,
                  MediaSourceId: activeMediaSourceId,
                  LiveStreamId: activeLiveStreamId,
                  PositionTicks: Math.floor(Number(newTime) * 10_000_000),
                  IsPaused: !state.playing,
                  IsMuted: state.isMuted,
                  VolumeLevel: Math.min(state.volume, 100),
                  CanSeek: true,
                  PlayMethod: PlayMethod.DirectStream,
                  AudioStreamIndex:
                    state.audioIndex >= 0 ? state.audioIndex : undefined,
                  SubtitleStreamIndex:
                    state.subtitleIndex > 0 ? state.subtitleIndex : undefined,
                },
              });
            } catch (_error) {
              // Do nothing
            }
          }
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.playBackStateChange.listen(({ payload }) => {
          const isPaused = payload.pause;
          setState("playing", !isPaused);
          setVideoState("pause", isPaused);
          if (!isPaused) {
            setBufferingState(false);
          }
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.audioTrackChange.listen(async ({ payload }) => {
          const tracks = payload.tracks as Track[];
          setState("audioList", tracks);
          if (audioIsManual) {
            return;
          }
          // Resolve preferred language: per-series > global > fallback
          // If metadata isn't current yet, getSeriesId() returns undefined
          // so we get global defaults; we'll re-resolve once metadata arrives.
          const metadataReady = isMetadataCurrent();
          const resolved = resolveLanguagePreferences(appPrefs, getSeriesId());
          const preferred = findTrackByLanguage(tracks, resolved.audioLanguage);
          if (preferred) {
            await commands.playbackChangeAudio(preferred.id.toString());
            setState("audioIndex", preferred.id as number);
          } else if (tracks.length > 0) {
            await commands.playbackChangeAudio(tracks[0].id.toString());
            setState("audioIndex", tracks[0].id);
          }
          audioStartupFinalized = metadataReady;
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.subtitleTrackChange.listen(async ({ payload }) => {
          const tracks = payload.tracks as Track[];
          setState("subtitleList", tracks);
          if (subtitleIsManual) {
            return;
          }
          // Resolve preferred language: per-series > global > fallback
          const metadataReady = isMetadataCurrent();
          const resolved = resolveLanguagePreferences(appPrefs, getSeriesId());
          // If preference is SUBTITLE_OFF, leave subtitles off
          if (resolved.subtitleLanguage === SUBTITLE_OFF) {
            await commands.playbackChangeSubtitle("0");
            setState("subtitleIndex", 0);
            subtitleStartupFinalized = metadataReady;
            return;
          }
          const preferred = findTrackByLanguage(
            tracks,
            resolved.subtitleLanguage
          );
          if (preferred) {
            await commands.playbackChangeSubtitle(preferred.id.toString());
            setState("subtitleIndex", preferred.id);
          }
          subtitleStartupFinalized = metadataReady;
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.audioChangeEvent.listen(({ payload }) => {
          setState("audioIndex", Number(payload.index));
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.subtitleChangeEvent.listen(({ payload }) => {
          setState("subtitleIndex", Number(payload.index));
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.speedEventChange.listen(({ payload }) => {
          setState("playbackSpeed", Number(payload.speed));
        })
      ))
    ) {
      return;
    }

    // Cache and buffering event listeners with debouncing
    let cacheUpdateTimeout: NodeJS.Timeout;
    if (
      !(await registerListener(
        events.cacheTimeChange.listen(({ payload }) => {
          const currentTime = Number(state.currentTime);
          const bufferedDuration = Number(payload.time);

          // Debounce cache updates to prevent excessive re-renders
          clearTimeout(cacheUpdateTimeout);
          cacheUpdateTimeout = setTimeout(() => {
            setState(
              "bufferedTime",
              Math.max(0, currentTime + bufferedDuration)
            );

            // Update loading state based on buffer
            if (state.isLoading && bufferedDuration > 0) {
              setState("isLoading", false);
            }
          }, 100);
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.bufferingStateChange.listen(({ payload }) => {
          const percentage = Number(payload.buffered);
          const clampedPercentage = Math.max(0, Math.min(100, percentage));
          const previousPercentage = state.bufferingPercentage;

          // Only update if percentage changed significantly to reduce re-renders
          if (Math.abs(clampedPercentage - previousPercentage) > 1) {
            setState("bufferingPercentage", clampedPercentage);
          }

          const transitionedToEmptyBuffer =
            clampedPercentage === 0 && previousPercentage > 0;
          const hasActivePlaybackProgress = hasRecentPlaybackProgress();

          const shouldShowBuffering =
            ((clampedPercentage > 0 && clampedPercentage < 100
              ? true
              : transitionedToEmptyBuffer) &&
              !hasActivePlaybackProgress) ||
            pausedForCache;

          setBufferingState(
            shouldShowBuffering &&
              state.playing &&
              !state.isLoading &&
              !state.isSeeking
          );
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.pauseForCacheChange.listen(({ payload }) => {
          const isPaused = payload.pause;
          pausedForCache = isPaused;

          setBufferingState(isPaused);

          // Show controls when paused for cache
          if (isPaused) {
            setState("isLoading", false);
            showControls();
          }
        })
      ))
    ) {
      return;
    }

    if (
      !(await registerListener(
        events.errorEventChange.listen(({ payload }) => {
          let message = "Playback failed";
          if (typeof payload?.message === "string") {
            message = String(payload.message);
          }

          setState("playbackError", message);
          setState("isLoading", false);
          setBufferingState(false, 0);
          showControls();
        })
      ))
    ) {
      return;
    }

    if (setupVersion === listenerSetupVersion) {
      unlistenFuncs = nextUnlistenFuncs;
    }
  });

  const offFullscreenIfOnWhenCleanup = async () => {
    const window = getCurrentWindow();
    if (await window.isFullscreen()) {
      commands.toggleFullscreen();
    }
  };

  onCleanup(async () => {
    listenerSetupVersion++;
    const itemId = state.currentItemId;
    const currentTime = state.currentTime;
    const ownsActivePlaybackSession =
      videoContext.activePlaybackSessionId === playbackSessionId;
    const isPipActive = await syncPipVisibility().catch(() => false);

    const teardownActions = planPlaybackSessionTeardown({
      ownsActivePlaybackSession,
      isPipActive,
    });

    if (teardownActions.includes("mark-paused")) {
      setVideoState("pause", true);
    }

    if (teardownActions.includes("destroy-pip-viewer")) {
      await commands.destroyPipWindow().catch(() => {
        // PiP teardown is best-effort; playback cleanup must continue.
      });
      setVideoState("isPip", false);
      setVideoState("isPipTransitioning", false);
    }

    resetTransientUiState();
    offFullscreenIfOnWhenCleanup();
    if (teardownActions.includes("clear-mpv")) {
      await clearPlaybackIfActiveSession();
    }
    unlistenFuncs.forEach((unlisten) => {
      unlisten();
    });
    clearHideControlsTimeout();
    clearTimeout(seekGuardTimeout);
    clearTimeout(bufferingResetTimeout);
    removeControlInteractionListeners();

    // Report playback stopped to Jellyfin
    if (jf.api) {
      try {
        const playstateApi = getPlaystateApi(jf.api);
        await playstateApi.reportPlaybackStopped({
          playbackStopInfo: {
            ItemId: itemId,
            PlaySessionId: playSessionId,
            MediaSourceId: activeMediaSourceId,
            LiveStreamId: activeLiveStreamId,
            PositionTicks: Math.floor(Number(currentTime) * 10_000_000),
          },
        });
      } catch (_error) {
        // Do nothing
      }
    }
  });

  const onEndOfFile = async () => {
    if (!jf.api) {
      return;
    }

    const playstateApi = getPlaystateApi(jf.api);
    await playstateApi.reportPlaybackStopped({
      playbackStopInfo: {
        ItemId: itemId(),
        PlaySessionId: playSessionId,
        MediaSourceId: activeMediaSourceId,
        LiveStreamId: activeLiveStreamId,
        PositionTicks: Math.floor(Number(state.currentTime) * 10_000_000),
      },
    });
  };

  return {
    state,
    setState,
    openPanel,
    setOpenPanel,
    showControls,
    toggleControlsLock,
    togglePlay,
    toggleMute,
    handleVolumeChange,
    setSpeed,
    handleProgressClick,
    handleOpenPip,
    loadNewVideo,
    handleControlMouseEnter,
    handleControlMouseLeave,
    handleControlInteractionStart,
    navigateToChapter,
    // Centralized track selection (manual)
    selectAudioTrack,
    selectSubtitleTrack,
    // OSD and help functions
    showOSD,
    hideOSD,
    toggleHelp,
    updateLoadingStage,
    updateNetworkQuality,
    updateBufferHealth,
    resetTransientUiState,
    clearPlaybackError,
    retryPlayback,
    onEndOfFile,
  };
}

import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client";
import { useNavigate } from "@solidjs/router";
import type { UnlistenFn } from "@tauri-apps/api/event";
import { Effect } from "effect";
import { createEffect, createMemo, createSignal, onCleanup } from "solid-js";
import { useRuntime } from "~/effect/runtime/use-runtime";
import { AuthService } from "~/effect/services/auth";
import type { WithImage } from "~/effect/services/jellyfin/service";
import { JellyfinService } from "~/effect/services/jellyfin/service";
import { commands, events } from "~/lib/tauri";

type UseAutoplayProps = {
  currentItem: () => WithImage<BaseItemDto> | undefined;
  onEndOfFile?: () => Promise<void>;
  playbackState: {
    currentTime: () => string;
    duration: () => number;
    paused: () => boolean;
  };
};

export function useAutoplay(props: UseAutoplayProps) {
  const navigate = useNavigate();
  const runtime = useRuntime();

  const [showAutoplay, setShowAutoplay] = createSignal(false);
  const [isCollapsed, setIsCollapsed] = createSignal(false);
  const [isCancelled, setIsCancelled] = createSignal(false);
  const [didPauseForAutoplay, setDidPauseForAutoplay] = createSignal(false);
  const [nextEpisode, setNextEpisode] = createSignal<
    WithImage<BaseItemDto> | undefined
  >(undefined);
  const [isNextEpisodeLoading, setIsNextEpisodeLoading] = createSignal(false);

  let playbackTimePollInterval: ReturnType<typeof setInterval> | undefined;
  let endOfFileUnlisten: UnlistenFn | undefined;
  let listenerSetupVersion = 0;

  let fetchVersion = 0;
  createEffect(() => {
    const currentItem = props.currentItem();
    const currentId = currentItem?.Id;
    const version = ++fetchVersion;

    if (!currentId || currentItem?.Type !== "Episode") {
      setNextEpisode(undefined);
      setIsNextEpisodeLoading(false);
      return;
    }

    // Clear stale nextEpisode immediately so the previous autoplay card does
    // not linger while we fetch the next episode for the new item.
    setNextEpisode(undefined);
    setIsNextEpisodeLoading(true);

    runtime
      .runPromise(
        Effect.gen(function* () {
          yield* AuthService;
          return yield* JellyfinService.pipe(
            Effect.flatMap((jf) => jf.getNextEpisode(currentItem))
          );
        })
      )
      .then((item) => {
        if (version !== fetchVersion) {
          return;
        }
        setNextEpisode(item);
      })
      .catch(() => {
        if (version !== fetchVersion) {
          return;
        }
        setNextEpisode(undefined);
      })
      .finally(() => {
        if (version !== fetchVersion) {
          return;
        }
        setIsNextEpisodeLoading(false);
      });
  });

  // Check if we should show autoplay when query completes
  createEffect(() => {
    // If nextEpisode query just completed and we're at 80%+, show autoplay
    if (
      !isNextEpisodeLoading() &&
      nextEpisode() &&
      !showAutoplay() &&
      !isCancelled()
    ) {
      const duration = props.playbackState.duration();
      const currentTime = Number(props.playbackState.currentTime());

      if (duration > 0 && currentTime > 0) {
        const progress = (currentTime / duration) * 100;

        if (progress >= 80 && props.currentItem()?.Type === "Episode") {
          // Show overlay without interrupting playback.
          setShowAutoplay(true);
        }
      }
    }
  });

  const hideAutoplay = () => {
    setShowAutoplay(false);
    setIsCollapsed(false);
    setIsCancelled(true); // Mark as cancelled to prevent showing again
    // Resume playback only if the prompt itself paused playback.
    if (didPauseForAutoplay()) {
      commands.playbackPlay();
    }
    setDidPauseForAutoplay(false);
  };

  const resetAutoplay = () => {
    setShowAutoplay(false);
    setIsCollapsed(false);
    setIsCancelled(false); // Reset cancelled state for new video
    setDidPauseForAutoplay(false);
  };

  const playNextEpisode = () => {
    const next = nextEpisode();
    if (!next?.Id) {
      return;
    }

    try {
      // Eagerly reset all autoplay state (including isCancelled) so the new
      // episode starts with a clean slate.  The item-change effect would
      // eventually do this once refreshed metadata arrives, but resetting now
      // closes the transient window where the new episode could inherit
      // isCancelled=true from the outgoing episode.
      // NOTE: we do NOT call commands.playbackPlay() — we are navigating away.
      resetAutoplay();

      // Navigate to the new episode
      navigate(`/video/${next.Id}`, { replace: true });
    } catch {
      setShowAutoplay(false);
    }
  };

  const handleEndOfFile = (reason: number) => {
    // Only show autoplay for natural end of file (reason 0 = MPV_END_FILE_REASON_EOF)
    // and only for episodes that have a next episode
    // Also check if we're at least 80% through the video
    // Don't show if user has already cancelled autoplay
    if (
      reason === 0 &&
      nextEpisode() &&
      props.currentItem()?.Type === "Episode" &&
      !isCancelled()
    ) {
      const duration = props.playbackState.duration();
      const currentTime = Number(props.playbackState.currentTime());

      if (duration > 0 && currentTime > 0) {
        const progress = (currentTime / duration) * 100;

        // Only show autoplay if we're at least 80% through the video
        // Also wait for nextEpisode query to complete
        if (
          progress >= 80 &&
          !showAutoplay() &&
          !isNextEpisodeLoading() &&
          nextEpisode()
        ) {
          // Show overlay without pausing playback.
          setShowAutoplay(true);
        }

        // Only auto-advance at >=95% if the overlay was never shown (i.e. the
        // user has not had a chance to interact with it).  When showAutoplay()
        // is true the overlay is already visible and the user should be able to
        // cancel or confirm; we leave navigation entirely to their action.
        if (
          progress >= 95 &&
          props.currentItem()?.Type === "Episode" &&
          !isCancelled() &&
          !showAutoplay()
        ) {
          playNextEpisode();
        }
      }
    }
  };

  const handlePlaybackTime = (time: string) => {
    // Check if we're at 80% of the video duration
    const duration = props.playbackState.duration();
    const currentTime = Number(time);

    if (duration > 0 && currentTime > 0) {
      const progress = (currentTime / duration) * 100;

      // Hide the overlay (without marking as cancelled) when the user scrubs
      // back below the 80% threshold — lets the overlay re-appear naturally if
      // they seek forward again without having explicitly dismissed it.
      if (progress < 80 && showAutoplay()) {
        setShowAutoplay(false);
        setIsCollapsed(false);
        // Resume playback only if the overlay had paused playback.
        if (didPauseForAutoplay()) {
          commands.playbackPlay();
        }
        setDidPauseForAutoplay(false);
        return;
      }

      // Show autoplay overlay when 80% complete and not already shown
      // Don't show if user has already cancelled autoplay
      // Also wait for nextEpisode query to complete
      if (
        progress >= 80 &&
        !showAutoplay() &&
        !isNextEpisodeLoading() &&
        nextEpisode() &&
        props.currentItem()?.Type === "Episode" &&
        !isCancelled()
      ) {
        // Show overlay without pausing playback.
        setShowAutoplay(true);
      }
    }
  };

  // Reset autoplay state when current item changes
  let lastItemId = "";
  createEffect(() => {
    const currentId = props.currentItem()?.Id;
    if (currentId && currentId !== lastItemId) {
      resetAutoplay();
      lastItemId = currentId;
    }
  });

  createEffect(async () => {
    const setupVersion = ++listenerSetupVersion;
    const currentID = props.currentItem()?.Id;

    // Always clean up existing listeners, even when current item is temporarily undefined.
    if (playbackTimePollInterval) {
      clearInterval(playbackTimePollInterval);
      playbackTimePollInterval = undefined;
    }
    if (endOfFileUnlisten) {
      endOfFileUnlisten();
      endOfFileUnlisten = undefined;
    }

    if (currentID) {
      // Poll playback time at a coarse interval (~1s) instead of reacting to
      // every high-frequency playBackTimeChange event.  The autoplay threshold
      // is 80% so sub-second precision is unnecessary.
      playbackTimePollInterval = setInterval(() => {
        handlePlaybackTime(props.playbackState.currentTime());
      }, 1000);

      // EOFEventChange payload is null; treat every natural EOF as reason 0
      const endOfFileListener = await events.eofEventChange.listen(async () => {
        try {
          await props.onEndOfFile?.();
        } catch {
          // onEndOfFile rejection must not block autoplay/next-episode handling
        }
        handleEndOfFile(0);
      });
      if (setupVersion !== listenerSetupVersion) {
        endOfFileListener();
        return;
      }
      endOfFileUnlisten = endOfFileListener;
    }
  });
  onCleanup(() => {
    listenerSetupVersion++;
    if (playbackTimePollInterval) {
      clearInterval(playbackTimePollInterval);
      playbackTimePollInterval = undefined;
    }
    if (endOfFileUnlisten) {
      endOfFileUnlisten();
      endOfFileUnlisten = undefined;
    }
  });

  // Create a memoized nextEpisode that will be reactive
  const nextEpisodeData = createMemo(() => nextEpisode());

  // Create a memoized return object to ensure reactivity
  const returnValue = createMemo(() => ({
    showAutoplay,
    isCollapsed,
    setIsCollapsed,
    nextEpisode: nextEpisodeData(),
    playNextEpisode,
    cancelAutoplay: hideAutoplay,
  }));

  return returnValue;
}

import type { BaseItemDto } from "@jellyfin/sdk/lib/generated-client";
import { ChevronDown, ChevronUp, Play, SkipForward, X } from "lucide-solid";
import { Show } from "solid-js";
import type { WithImage } from "~/effect/services/jellyfin/service";

type AutoplayOverlayProps = {
  nextEpisode: WithImage<BaseItemDto>;
  onPlayNext: () => void;
  onCancel: () => void;
  isVisible: boolean;
  isCollapsed: boolean;
  setIsCollapsed: (collapsed: boolean) => void;
};

export default function AutoplayOverlay(props: AutoplayOverlayProps) {
  const handlePlayNow = () => {
    props.onPlayNext();
  };

  const handleCancel = () => {
    props.onCancel();
  };

  return (
    <Show when={props.isVisible && props.nextEpisode}>
      <div class="pointer-events-none fixed inset-0 z-50">
        <div class="pointer-events-auto absolute right-4 bottom-4">
          {/* Card — matches the controls-bar visual language */}
          <div
            class="w-80 max-w-sm rounded-2xl border border-white/[0.09] bg-black/80 shadow-[0_20px_60px_rgba(0,0,0,0.8),inset_0_1px_0_rgba(255,255,255,0.07)] backdrop-blur-[28px] transition-all duration-300"
            classList={{
              "p-2.5": props.isCollapsed,
              "p-4": !props.isCollapsed,
            }}
          >
            {/* Header */}
            <div
              class="flex items-center justify-between"
              classList={{ "mb-3": !props.isCollapsed }}
            >
              <div class="flex items-center gap-2">
                {/* Amber-tinted icon badge — mirrors the play-button ring style */}
                <div class="flex h-6 w-6 items-center justify-center rounded-lg bg-amber-400/[0.12] ring-1 ring-amber-400/[0.18] ring-inset">
                  <SkipForward class="h-3 w-3 text-amber-300" />
                </div>
                <h3 class="font-semibold text-sm text-white tracking-tight">
                  Next Episode
                </h3>
              </div>

              <div class="flex items-center gap-0.5">
                {/* Collapse toggle */}
                <button
                  aria-label={
                    props.isCollapsed
                      ? "Expand autoplay card"
                      : "Collapse autoplay card"
                  }
                  class="flex h-7 w-7 items-center justify-center rounded-xl text-white/45 transition-all duration-150 hover:bg-white/[0.08] hover:text-white/90 active:scale-[0.88]"
                  onClick={(e) => {
                    e.stopPropagation();
                    props.setIsCollapsed(!props.isCollapsed);
                  }}
                >
                  <Show
                    fallback={<ChevronDown class="h-3.5 w-3.5" />}
                    when={props.isCollapsed}
                  >
                    <ChevronUp class="h-3.5 w-3.5" />
                  </Show>
                </button>

                {/* Dismiss */}
                <button
                  aria-label="Dismiss next-episode prompt"
                  class="flex h-7 w-7 items-center justify-center rounded-xl text-white/45 transition-all duration-150 hover:bg-white/[0.08] hover:text-white/90 active:scale-[0.88]"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleCancel();
                  }}
                >
                  <X class="h-3.5 w-3.5" />
                </button>
              </div>
            </div>

            {/* Episode info + actions — only when expanded */}
            <Show when={!props.isCollapsed}>
              <div class="mb-3">
                <h4 class="mb-1 line-clamp-1 font-semibold text-sm text-white tracking-tight">
                  {props.nextEpisode?.Name}
                </h4>
                <Show when={props.nextEpisode?.SeriesName}>
                  <p class="mb-1 font-mono text-[11px] text-white/40 tabular-nums tracking-tight">
                    {props.nextEpisode?.SeriesName}
                    <Show when={props.nextEpisode?.IndexNumber}>
                      {" "}
                      · Ep {props.nextEpisode?.IndexNumber}
                    </Show>
                  </p>
                </Show>
                <Show when={props.nextEpisode?.Overview}>
                  <p class="line-clamp-2 text-[12px] text-white/50 leading-relaxed">
                    {props.nextEpisode?.Overview}
                  </p>
                </Show>
              </div>

              {/* ── Action Buttons — mirror play-button & secondary-button styles ── */}
              <div class="flex gap-2">
                {/* Primary — amber accent, mirrors the paused play-button */}
                <button
                  class="flex flex-1 items-center justify-center gap-1.5 rounded-xl bg-amber-400/[0.12] px-3 py-2 font-semibold text-amber-300 text-sm ring-1 ring-amber-400/[0.18] ring-inset transition-all duration-150 hover:bg-amber-400/[0.2] hover:ring-amber-400/[0.25] active:scale-[0.96]"
                  onClick={(e) => {
                    e.stopPropagation();
                    handlePlayNow();
                  }}
                >
                  <Play class="h-3 w-3" fill="currentColor" />
                  Play Now
                </button>

                {/* Secondary — matches ghost/tertiary button style in controls */}
                <button
                  class="rounded-xl border border-white/[0.09] bg-white/[0.04] px-3 py-2 text-sm text-white/55 transition-all duration-150 hover:bg-white/[0.08] hover:text-white/80 active:scale-[0.96]"
                  onClick={(e) => {
                    e.stopPropagation();
                    handleCancel();
                  }}
                >
                  Cancel
                </button>
              </div>
            </Show>
          </div>
        </div>
      </div>
    </Show>
  );
}

import { useNavigate } from "@solidjs/router";
import { Show } from "solid-js";

type VideoInfoOverlayProps = {
  /** When true the cached data belongs to a previous item; hide overlay until fresh data arrives. */
  isStale?: boolean;
  itemDetails: {
    data?: {
      Name?: string | null;
      SeriesName?: string | null;
      Overview?: string | null;
      Type?: string | null;
      Id?: string | null;
      ParentId?: string | null;
      SeriesId?: string | null;
      IndexNumber?: number | null;
      ParentIndexNumber?: number | null;
    };
  };
  seriesDetails: {
    data?: {
      Id?: string | null;
      ParentId?: string | null;
    };
  };
};

export default function VideoInfoOverlay(props: VideoInfoOverlayProps) {
  const navigate = useNavigate();

  return (
    <Show when={props.itemDetails.data && !props.isStale}>
      <div class="pointer-events-none fixed inset-0">
        {/* Top gradient — deep navy cinematic fade */}
        <div class="pointer-events-none absolute top-0 right-0 left-0 bg-gradient-to-b from-[#080c16]/95 via-[#080c16]/50 to-transparent pt-0 pb-28">
          <div class="mx-auto max-w-lg px-6 pt-16 text-white">
            {/* Episode / Season meta */}
            <Show
              when={
                props.itemDetails.data?.Type === "Episode" &&
                (props.itemDetails.data?.ParentIndexNumber ||
                  props.itemDetails.data?.IndexNumber)
              }
            >
              <div class="mb-2.5 text-center font-mono text-[10px] text-blue-300/50 uppercase tracking-[0.25em]">
                <Show when={props.itemDetails.data?.ParentIndexNumber}>
                  S{props.itemDetails.data?.ParentIndexNumber}
                </Show>
                <Show
                  when={
                    props.itemDetails.data?.ParentIndexNumber &&
                    props.itemDetails.data?.IndexNumber
                  }
                >
                  &thinsp;·&thinsp;
                </Show>
                <Show when={props.itemDetails.data?.IndexNumber}>
                  E{props.itemDetails.data?.IndexNumber}
                </Show>
              </div>
            </Show>

            {/* Primary title */}
            <h1 class="mb-2.5 text-center font-semibold text-[22px] text-white leading-tight tracking-tight drop-shadow-[0_2px_16px_rgba(0,0,0,0.9)]">
              {props.itemDetails.data?.Name}
            </h1>

            {/* Series link */}
            <Show
              when={
                props.itemDetails.data?.Type === "Episode" &&
                props.itemDetails.data?.SeriesName &&
                props.itemDetails.data?.SeriesId &&
                props.seriesDetails.data?.ParentId &&
                props.seriesDetails.data?.Id ===
                  props.itemDetails.data?.SeriesId
              }
            >
              <button
                class="pointer-events-auto mx-auto mb-3 block cursor-pointer text-center text-[13px] text-blue-300/45 drop-shadow-md transition-colors duration-150 hover:text-blue-200/75"
                onClick={(e) => {
                  e.stopPropagation();
                  const libraryId = props.seriesDetails.data?.ParentId;
                  const seriesId = props.itemDetails.data?.SeriesId;
                  if (!libraryId) {
                    return;
                  }
                  if (!seriesId) {
                    return;
                  }
                  navigate(`/library/${libraryId}/item/${seriesId}`);
                }}
              >
                {props.itemDetails.data?.SeriesName}
              </button>
            </Show>

            {/* Movie "view details" */}
            <Show when={props.itemDetails.data?.Type === "Movie"}>
              <button
                class="pointer-events-auto mx-auto mb-3 block cursor-pointer text-center text-[12px] text-white/30 drop-shadow-md transition-colors duration-150 hover:text-white/60"
                onClick={(e) => {
                  e.stopPropagation();
                  navigate(
                    `/library/${props.itemDetails.data?.ParentId}/item/${props.itemDetails.data?.Id}`
                  );
                }}
              >
                View details
              </button>
            </Show>

            <Show when={props.itemDetails.data?.Overview}>
              <p class="line-clamp-2 text-center text-[12px] text-white/40 leading-relaxed drop-shadow-md">
                {props.itemDetails.data?.Overview}
              </p>
            </Show>
          </div>
        </div>
      </div>
    </Show>
  );
}

